1	import { component$, useSignal, useVisibleTask$, $ } from "@builder.io/qwik";
2	import type { DocumentHead } from "@builder.io/qwik-city";
3	import { css } from "styled-system/css";
4	import { flex, grid, hstack } from "styled-system/patterns";
5	import { Nav } from "~/components/layout/nav";
6	import { Footer } from "~/components/layout/footer";
7	
8	const API_BASE = "http://localhost:3456/api";
9	
10	interface PersonaShort {
11	  id: string;
12	  name: string;
13	  summary: string;
14	  _source?: string;
15	  aesthetic?: { colorTemperature?: string; density?: string };
16	}
17	
18	const AESTHETIC_FIELDS = [
19	  { key: "colorTemperature", label: "Color Temperature", options: ["warm", "cool", "neutral", "high-contrast", "muted"] },
20	  { key: "density", label: "Density", options: ["minimal", "dense", "rich", "maximalist"] },
21	  { key: "edgeStyle", label: "Edge Style", options: ["sharp", "soft", "organic", "geometric", "brutalist"] },
22	  { key: "motionStyle", label: "Motion Style", options: ["smooth", "snappy", "liquid", "mechanical"] },
23	  { key: "typographyStyle", label: "Typography", options: ["clean", "expressive", "retro", "futuristic", "handcrafted"] },
24	  { key: "textureStyle", label: "Texture", options: ["flat", "textured", "noisy", "clean", "grainy"] },
25	  { key: "iconStyle", label: "Icon Style", options: ["line", "filled", "hand-drawn", "geometric", "abstract"] },
26	  { key: "layoutStyle", label: "Layout", options: ["grid", "organic", "asymmetric", "brutalist", "editorial"] },
27	];
28	
29	export default component$(() => {
30	  const activeTab = useSignal<"personas" | "create" | "generate" | "tokens">("personas");
31	  const toastMsg = useSignal("");
32	  const toastType = useSignal("success");
33	  const toastShow = useSignal(false);
34	
35	  const personas = useSignal<PersonaShort[]>([]);
36	  const personasLoading = useSignal(true);
37	
38	  const editingId = useSignal<string | null>(null);
39	  const pId = useSignal("");
40	  const pName = useSignal("");
41	  const pSummary = useSignal("");
42	  const pRegion = useSignal("");
43	  const pSubcultures = useSignal("");
44	  const pValues = useSignal("");
45	  const pFilms = useSignal("");
46	  const pAnime = useSignal("");
47	  const pMusicGenres = useSignal("");
48	  const pMusicArtists = useSignal("");
49	  const pVisualArtists = useSignal("");
50	  const pSpaces = useSignal("");
51	  const pObsessions = useSignal("");
52	  const pInterfaceValues = useSignal("");
53	  const pPetPeeves = useSignal("");
54	  const pColorTemp = useSignal("neutral");
55	  const pDensity = useSignal("rich");
56	  const pEdge = useSignal("soft");
57	  const pMotion = useSignal("smooth");
58	  const pTypography = useSignal("expressive");
59	  const pTexture = useSignal("textured");
60	  const pIcon = useSignal("line");
61	  const pLayout = useSignal("organic");
62	
63	  const genSelected = useSignal("");
64	  const genType = useSignal("suite");
65	  const genDryRun = useSignal(false);
66	  const genRunning = useSignal(false);
67	  const genLogs = useSignal<string[]>([]);
68	  const genJobStatus = useSignal("");
69	  const genJobs = useSignal<Array<{ id: string; personaId: string; type: string; status: string }>>([]);
70	
71	  const tokSelected = useSignal("");
72	  const tokFormat = useSignal("css");
73	  const tokContent = useSignal("");
74	  const tokLoading = useSignal(false);
75	
76	  const showToast = $((msg: string, type = "success") => {
77	    toastMsg.value = msg;
78	    toastType.value = type;
79	    toastShow.value = true;
80	    setTimeout(() => toastShow.value = false, 3000);
81	  });
82	
83	  const loadPersonas = $(() => {
84	    personasLoading.value = true;
85	    fetch(`${API_BASE}/personas`)
86	      .then((r) => r.json())
87	      .then((data) => { personas.value = data; personasLoading.value = false; })
88	      .catch(() => { personasLoading.value = false; });
89	  });
90	
91	  useVisibleTask$(() => {
92	    loadPersonas();
93	    fetch(`${API_BASE}/jobs`).then((r) => r.json()).then((d) => { genJobs.value = d; }).catch(() => {});
94	  });
95	
96	  const resetForm = $(() => {
97	    pId.value = "";
98	    pName.value = "";
99	    pSummary.value = "";
100	    pRegion.value = "";
101	    pSubcultures.value = "";
102	    pValues.value = "";
103	    pFilms.value = "";
104	    pAnime.value = "";
105	    pMusicGenres.value = "";
106	    pMusicArtists.value = "";
107	    pVisualArtists.value = "";
108	    pSpaces.value = "";
109	    pObsessions.value = "";
110	    pInterfaceValues.value = "";
111	    pPetPeeves.value = "";
112	    pColorTemp.value = "neutral";
113	    pDensity.value = "rich";
114	    pEdge.value = "soft";
115	    pMotion.value = "smooth";
116	    pTypography.value = "expressive";
117	    pTexture.value = "textured";
118	    pIcon.value = "line";
119	    pLayout.value = "organic";
120	    editingId.value = null;
121	  });
122	
123	  const fillForm = $((p: any) => {
124	    pId.value = p.id;
125	    pName.value = p.name;
126	    pSummary.value = p.summary || "";
127	    pRegion.value = p.culture?.region || "";
128	    pSubcultures.value = (p.culture?.subcultures || []).join(", ");
129	    pValues.value = (p.culture?.values || []).join(", ");
130	    pFilms.value = (p.influences?.films || []).join(", ");
131	    pAnime.value = (p.influences?.anime || []).join(", ");
132	    pMusicGenres.value = (p.influences?.music?.genres || []).join(", ");
133	    pMusicArtists.value = (p.influences?.music?.artists || []).join(", ");
134	    pVisualArtists.value = (p.influences?.visualArtists || []).join(", ");
135	    pSpaces.value = (p.influences?.spaces || []).join(", ");
136	    pObsessions.value = (p.influences?.obsessions || []).join(", ");
137	    pInterfaceValues.value = (p.behaviors?.interfaceValues || []).join(", ");
138	    pPetPeeves.value = (p.behaviors?.petPeeves || []).join(", ");
139	    pColorTemp.value = p.aesthetic?.colorTemperature || "neutral";
140	    pDensity.value = p.aesthetic?.density || "rich";
141	    pEdge.value = p.aesthetic?.edgeStyle || "soft";
142	    pMotion.value = p.aesthetic?.motionStyle || "smooth";
143	    pTypography.value = p.aesthetic?.typographyStyle || "expressive";
144	    pTexture.value = p.aesthetic?.textureStyle || "textured";
145	    pIcon.value = p.aesthetic?.iconStyle || "line";
146	    pLayout.value = p.aesthetic?.layoutStyle || "organic";
147	  });
148	
149	  const savePersona = $(() => {
150	    const split = (v: string) => v.split(",").map((s) => s.trim()).filter(Boolean);
151	    const persona = {
152	      id: pId.value.trim(),
153	      name: pName.value.trim() || pId.value.trim(),
154	      summary: pSummary.value.trim(),
155	      culture: { region: pRegion.value.trim() || undefined, subcultures: split(pSubcultures.value), values: split(pValues.value) },
156	      influences: {
157	        films: split(pFilms.value), shows: [], anime: split(pAnime.value),
158	        music: { genres: split(pMusicGenres.value), artists: split(pMusicArtists.value) },
159	        games: [], visualArtists: split(pVisualArtists.value), fashion: [], spaces: split(pSpaces.value),
160	        tools: [], obsessions: split(pObsessions.value),
161	      },
162	      behaviors: {
163	        discovery: [], interfaceValues: split(pInterfaceValues.value), platforms: [],
164	        expression: [], petPeeves: split(pPetPeeves.value),
165	      },
166	      aesthetic: {
167	        colorTemperature: pColorTemp.value, density: pDensity.value, edgeStyle: pEdge.value,
168	        motionStyle: pMotion.value, typographyStyle: pTypography.value, textureStyle: pTexture.value,
169	        iconStyle: pIcon.value, layoutStyle: pLayout.value,
170	        visualKeywords: [...split(pFilms.value), ...split(pAnime.value), ...split(pVisualArtists.value)].slice(0, 8),
171	        moodKeywords: [...split(pValues.value), ...split(pInterfaceValues.value)].slice(0, 6),
172	      },
173	    };
174	    const url = editingId.value ? `${API_BASE}/personas/${editingId.value}` : `${API_BASE}/personas`;
175	    const method = editingId.value ? "PUT" : "POST";
176	    fetch(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(persona) })
177	      .then((r) => { if (!r.ok) throw new Error(); showToast(editingId.value ? "Updated" : "Created"); resetForm(); activeTab.value = "personas"; loadPersonas(); })
178	      .catch(() => showToast("Save failed", "error"));
179	  });
180	
181	  const loadTokens = $((id: string, fmt: string) => {
182	    if (!id) return;
183	    tokLoading.value = true;
184	    fetch(`${API_BASE}/tokens/${id}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ format: fmt }) })
185	      .then((r) => r.json())
186	      .then((data) => { tokContent.value = data.content || ""; tokLoading.value = false; })
187	      .catch(() => { tokLoading.value = false; });
188	  });
189	
190	  const deletePersona = $((id: string) => {
191	    if (!confirm("Delete this persona?")) return;
192	    fetch(`${API_BASE}/personas/${id}`, { method: "DELETE" })
193	      .then(() => { showToast("Deleted"); loadPersonas(); })
194	      .catch(() => showToast("Delete failed", "error"));
195	  });
196	
197	  const startGeneration = $(() => {
198	    if (!genSelected.value) { showToast("Select a persona", "warn"); return; }
199	    genRunning.value = true;
200	    genLogs.value = [];
201	    genJobStatus.value = "running";
202	    fetch(`${API_BASE}/generate/${genSelected.value}`, {
203	      method: "POST",
204	      headers: { "Content-Type": "application/json" },
205	      body: JSON.stringify({ type: genType.value, dryRun: genDryRun.value }),
206	    })
207	      .then((r) => r.json())
208	      .then((data) => {
209	        genLogs.value = [`Job ${data.jobId} started`];
210	        const iv = setInterval(() => {
211	          fetch(`${API_BASE}/jobs/${data.jobId}`)
212	            .then((r) => r.json())
213	            .then((job) => {
214	              genJobStatus.value = job.status;
215	              genLogs.value = job.logs || [];
216	              if (job.status === "completed" || job.status === "error") {
217	                clearInterval(iv);
218	                genRunning.value = false;
219	                if (job.status === "completed") showToast("Generation complete!");
220	                else showToast(job.error || "Generation failed", "error");
221	                fetch(`${API_BASE}/jobs`).then((r) => r.json()).then((d) => { genJobs.value = d; }).catch(() => {});
222	              }
223	            })
224	            .catch(() => { clearInterval(iv); genRunning.value = false; });
225	        }, 1500);
226	      })
227	      .catch((err) => { genRunning.value = false; showToast(err.message, "error"); });
228	  });
229	
230	  const previewPrompts = $(() => {
231	    if (!genSelected.value) { showToast("Select a persona", "warn"); return; }
232	    fetch(`${API_BASE}/prompts/${genSelected.value}`, { method: "POST" })
233	      .then((r) => r.json())
234	      .then((data) => {
235	        genLogs.value = ["--- Prompt Preview ---", `Image: ${data.image?.prompt?.slice(0, 200)}...`, `SVG: ${data.svg?.prompt?.slice(0, 200)}...`];
236	      })
237	      .catch(() => showToast("Preview failed", "error"));
238	  });
239	
240	  const inputCls = css({ w: "full", bg: "bg", border: "1px solid token(colors.border)", color: "text", px: 3, py: 2, rounded: "md", fontSize: "sm" });
241	  const labelCls = css({ display: "block", fontSize: "xs", color: "text-muted", mb: 1 });
242	  const sectionTitle = css({ mt: 2, mb: 1, fontSize: "md", fontWeight: "semibold" });
243	
244	  return (
245	    <>
246	      <Nav />
247	      <main class={css({ pt: "80px", minH: "100vh", bg: "bg" })}>
248	        <div class={flex({ maxW: "7xl", mx: "auto", px: 6, py: 8, direction: "column", gap: 6 })}>
249	          <div class={flex({ align: "center", justify: "space-between", wrap: "wrap", gap: 4 })}>
250	            <div>
251	              <h1 class={css({ fontFamily: "heading", fontSize: "2xl", fontWeight: "bold", bgGradient: "to-r", gradientFrom: "orange.500", gradientTo: "amber.500", bgClip: "text", color: "transparent" })}>
252	                Baste Dashboard
253	              </h1>
254	              <p class={css({ color: "text-muted", fontSize: "sm", mt: 1 })}>
255	                Manage personas, generate assets, export design tokens
256	              </p>
257	            </div>
258	            <div class={hstack({ gap: 2, bg: "surface", p: 1, rounded: "lg", border: "1px solid token(colors.border)" })}>
259	              {(["personas", "create", "generate", "tokens"] as const).map((tab) => (
260	                <button
261	                  key={tab}
262	                  onClick$={() => { activeTab.value = tab; if (tab === "create") { resetForm(); editingId.value = null; } }}
263	                  class={css({
264	                    px: 4, py: 2, rounded: "md", fontSize: "sm", fontWeight: "medium", cursor: "pointer", border: "none",
265	                    transition: "all 0.2s",
266	                    bg: activeTab.value === tab ? "accent" : "transparent",
267	                    color: activeTab.value === tab ? "white" : "text-muted",
268	                    _hover: { bg: activeTab.value === tab ? "accent" : "surface-hover", color: activeTab.value === tab ? "white" : "text" },
269	                  })}
270	                >
271	                  {tab === "personas" ? "Personas" : tab === "create" ? (editingId.value ? "Edit" : "Create") : tab === "generate" ? "Generate" : "Tokens"}
272	                </button>
273	              ))}
274	            </div>
275	          </div>
276	
277	          {activeTab.value === "personas" && (
278	            <div>
279	              <div class={flex({ align: "center", justify: "space-between", mb: 4 })}>
280	                <h2 class={css({ fontFamily: "heading", fontSize: "xl", fontWeight: "semibold" })}>Your Personas</h2>
281	                <button onClick$={loadPersonas} class={css({ px: 3, py: 1.5, rounded: "md", bg: "surface-hover", color: "text", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border" } })}>Refresh</button>
282	              </div>
283	              {personasLoading.value && personas.value.length === 0 && (
284	                <div class={css({ color: "text-muted", textAlign: "center", py: 12 })}>Loading personas...</div>
285	              )}
286	              {!personasLoading.value && personas.value.length === 0 && (
287	                <div class={css({ color: "text-muted", textAlign: "center", py: 12 })}>No personas yet. Create your first!</div>
288	              )}
289	              <div class={grid({ columns: { base: 1, md: 2, lg: 3 }, gap: 4 })}>
290	                {personas.value.map((p) => (
291	                  <div key={p.id} class={css({ bg: "surface", border: "1px solid token(colors.border)", rounded: "lg", p: 5, transition: "all 0.2s", _hover: { borderColor: "accent", transform: "translateY(-2px)" } })}>
292	                    <div class={flex({ align: "center", justify: "space-between", mb: 2 })}>
293	                      <h3 class={css({ fontWeight: "semibold", fontSize: "lg" })}>{p.name}</h3>
294	                      <span class={css({ fontSize: "xs", px: 2, py: 0.5, rounded: "sm", bg: p._source === "base" ? "rgba(46,204,113,0.15)" : "rgba(230,126,34,0.15)", color: p._source === "base" ? "success" : "#e67e22" })}>{p._source || "base"}</span>
295	                    </div>
296	                    <p class={css({ color: "text-muted", fontSize: "sm", mb: 3 })}>{p.summary || "No summary"}</p>
297	                    <div class={hstack({ gap: 2, mb: 3 })}>
298	                      {p.aesthetic?.colorTemperature && <span class={css({ fontSize: "xs", px: 2, py: 0.5, rounded: "sm", bg: "rgba(123,104,238,0.15)", color: "accent-hover" })}>{p.aesthetic.colorTemperature}</span>}
299	                      {p.aesthetic?.density && <span class={css({ fontSize: "xs", px: 2, py: 0.5, rounded: "sm", bg: "rgba(123,104,238,0.15)", color: "accent-hover" })}>{p.aesthetic.density}</span>}
300	                    </div>
301	                    <div class={hstack({ gap: 2 })}>
302	                      <button onClick$={() => { genSelected.value = p.id; activeTab.value = "generate"; }} class={css({ flex: 1, px: 3, py: 1.5, rounded: "md", bg: "accent", color: "white", fontSize: "sm", fontWeight: "medium", border: "none", cursor: "pointer", _hover: { bg: "accent-hover" } })}>Generate</button>
303	                      <button onClick$={() => { tokSelected.value = p.id; loadTokens(p.id, tokFormat.value); activeTab.value = "tokens"; }} class={css({ px: 3, py: 1.5, rounded: "md", bg: "surface-hover", color: "text", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border" } })}>Tokens</button>
304	                      {p._source !== "base" && (
305	                        <>
306	                          <button onClick$={() => { fetch(`${API_BASE}/personas/${p.id}`).then((r) => r.json()).then((data) => { fillForm(data); editingId.value = p.id; activeTab.value = "create"; }); }} class={css({ px: 3, py: 1.5, rounded: "md", bg: "surface-hover", color: "text-muted", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border", color: "text" } })}>Edit</button>
307	                          <button onClick$={() => deletePersona(p.id)} class={css({ px: 3, py: 1.5, rounded: "md", bg: "surface-hover", color: "text-muted", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border", color: "text" } })}>Del</button>
308	                        </>
309	                      )}
310	                    </div>
311	                  </div>
312	                ))}
313	              </div>
314	            </div>
315	          )}
316	
317	          {activeTab.value === "create" && (
318	            <div class={css({ maxW: "800px" })}>
319	              <div class={flex({ align: "center", justify: "space-between", mb: 4, wrap: "wrap", gap: 2 })}>
320	                <h2 class={css({ fontFamily: "heading", fontSize: "xl", fontWeight: "semibold" })}>{editingId.value ? "Edit Persona" : "Create Persona"}</h2>
321	                <div class={flex({ gap: 2 })}>
322	                  <button onClick$={() => { resetForm(); activeTab.value = "personas"; }} class={css({ px: 4, py: 2, rounded: "md", bg: "surface-hover", color: "text", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border" } })}>Cancel</button>
323	                  <button onClick$={savePersona} class={css({ px: 4, py: 2, rounded: "md", bg: "accent", color: "white", fontSize: "sm", fontWeight: "medium", border: "none", cursor: "pointer", _hover: { bg: "accent-hover" } })}>Save</button>
324	                </div>
325	              </div>
326	              <div class={grid({ gap: 4 })}>
327	                <div><label class={labelCls}>ID (kebab-case)</label><input value={pId.value} onInput$={(e) => { pId.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="my-persona" /></div>
328	                <div><label class={labelCls}>Name</label><input value={pName.value} onInput$={(e) => { pName.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="My Persona Name" /></div>
329	                <div><label class={labelCls}>Summary</label><textarea value={pSummary.value} onInput$={(e) => { pSummary.value = (e.target as HTMLTextAreaElement).value; }} class={inputCls} placeholder="Brief description..." style={{ minHeight: "80px" }} /></div>
330	
331	                <h3 class={sectionTitle}>Culture</h3>
332	                <div class={grid({ columns: { base: 1, md: 2 }, gap: 4 })}>
333	                  <div><label class={labelCls}>Region</label><input value={pRegion.value} onInput$={(e) => { pRegion.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="e.g. Pacific Northwest" /></div>
334	                  <div><label class={labelCls}>Subcultures</label><input value={pSubcultures.value} onInput$={(e) => { pSubcultures.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="solarpunk, biohacking" /></div>
335	                </div>
336	                <div><label class={labelCls}>Values</label><input value={pValues.value} onInput$={(e) => { pValues.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="interconnectedness, growth" /></div>
337	
338	                <h3 class={sectionTitle}>Influences</h3>
339	                <div class={grid({ columns: { base: 1, md: 2 }, gap: 4 })}>
340	                  <div><label class={labelCls}>Films</label><input value={pFilms.value} onInput$={(e) => { pFilms.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="Annihilation, Nausicaä" /></div>
341	                  <div><label class={labelCls}>Anime</label><input value={pAnime.value} onInput$={(e) => { pAnime.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="Mushishi" /></div>
342	                  <div><label class={labelCls}>Music Genres</label><input value={pMusicGenres.value} onInput$={(e) => { pMusicGenres.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="ambient" /></div>
343	                  <div><label class={labelCls}>Music Artists</label><input value={pMusicArtists.value} onInput$={(e) => { pMusicArtists.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="Biosphere" /></div>
344	                </div>
345	                <div><label class={labelCls}>Visual Artists</label><input value={pVisualArtists.value} onInput$={(e) => { pVisualArtists.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="Ernst Haeckel" /></div>
346	                <div><label class={labelCls}>Spaces</label><input value={pSpaces.value} onInput$={(e) => { pSpaces.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="greenhouses" /></div>
347	                <div><label class={labelCls}>Obsessions</label><input value={pObsessions.value} onInput$={(e) => { pObsessions.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="mycelial networks" /></div>
348	
349	                <h3 class={sectionTitle}>Behaviors</h3>
350	                <div class={grid({ columns: { base: 1, md: 2 }, gap: 4 })}>
351	                  <div><label class={labelCls}>Interface Values</label><input value={pInterfaceValues.value} onInput$={(e) => { pInterfaceValues.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="discoverability" /></div>
352	                  <div><label class={labelCls}>Pet Peeves</label><input value={pPetPeeves.value} onInput$={(e) => { pPetPeeves.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="dark patterns" /></div>
353	                </div>
354	
355	                <h3 class={sectionTitle}>Aesthetic</h3>
356	                <div class={grid({ columns: { base: 1, md: 2 }, gap: 4 })}>
357	                  {AESTHETIC_FIELDS.map((f) => {
358	                    const valMap: Record<string, any> = {
359	                      colorTemperature: pColorTemp, density: pDensity, edgeStyle: pEdge, motionStyle: pMotion,
360	                      typographyStyle: pTypography, textureStyle: pTexture, iconStyle: pIcon, layoutStyle: pLayout,
361	                    };
362	                    const s = valMap[f.key];
363	                    return (
364	                      <div key={f.key}>
365	                        <label class={labelCls}>{f.label}</label>
