423	                {genJobs.value.map((j) => <div key={j.id} class={css({ fontSize: "xs", px: 2, py: 1, rounded: "sm", bg: "surface-hover", color: "text-muted" })}>{j.id} — {j.type} for {j.personaId} ({j.status})</div>)}
