450	              {!tokLoading.value && tokContent.value && (
451	                <>
452	                  <div class={hstack({ gap: 2, mb: 3 })}>
453	                    <button onClick$={() => { if (!tokContent.value || !tokSelected.value) return; const extMap: Record<string, string> = { css: "css", tailwind: "js", json: "json", panda: "ts" }; const ext = extMap[tokFormat.value] || "txt"; const blob = new Blob([tokContent.value], { type: "text/plain" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `${tokSelected.value}-tokens.${ext}`; a.click(); showToast(`Downloaded ${tokFormat.value === "panda" ? "PandaCSS" : tokFormat.value.toUpperCase()}`); }} class={css({ px: 4, py: 2, rounded: "md", bg: "accent", color: "white", fontSize: "sm", fontWeight: "medium", border: "none", cursor: "pointer", _hover: { bg: "accent-hover" } })}>Download {tokFormat.value === "panda" ? "PandaCSS" : tokFormat.value.toUpperCase()}</button>
454	                  </div>
