import { component$, useSignal, useVisibleTask$, $ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";
import { css } from "styled-system/css";
import { flex, grid, hstack } from "styled-system/patterns";
import { Nav } from "~/components/layout/nav";
import { Footer } from "~/components/layout/footer";

const API_BASE = "http://localhost:3456/api";

interface PersonaShort {
  id: string;
  name: string;
  summary: string;
  _source?: string;
  aesthetic?: { colorTemperature?: string; density?: string };
}

const AESTHETIC_FIELDS = [
  { key: "colorTemperature", label: "Color Temperature", options: ["warm", "cool", "neutral", "high-contrast", "muted"] },
  { key: "density", label: "Density", options: ["minimal", "dense", "rich", "maximalist"] },
  { key: "edgeStyle", label: "Edge Style", options: ["sharp", "soft", "organic", "geometric", "brutalist"] },
  { key: "motionStyle", label: "Motion Style", options: ["smooth", "snappy", "liquid", "mechanical"] },
  { key: "typographyStyle", label: "Typography", options: ["clean", "expressive", "retro", "futuristic", "handcrafted"] },
  { key: "textureStyle", label: "Texture", options: ["flat", "textured", "noisy", "clean", "grainy"] },
  { key: "iconStyle", label: "Icon Style", options: ["line", "filled", "hand-drawn", "geometric", "abstract"] },
  { key: "layoutStyle", label: "Layout", options: ["grid", "organic", "asymmetric", "brutalist", "editorial"] },
];

export default component$(() => {
  const activeTab = useSignal<"personas" | "create" | "generate" | "tokens">("personas");
  const toastMsg = useSignal("");
  const toastType = useSignal("success");
  const toastShow = useSignal(false);

  const personas = useSignal<PersonaShort[]>([]);
  const personasLoading = useSignal(true);

  const editingId = useSignal<string | null>(null);
  const pId = useSignal("");
  const pName = useSignal("");
  const pSummary = useSignal("");
  const pRegion = useSignal("");
  const pSubcultures = useSignal("");
  const pValues = useSignal("");
  const pFilms = useSignal("");
  const pAnime = useSignal("");
  const pMusicGenres = useSignal("");
  const pMusicArtists = useSignal("");
  const pVisualArtists = useSignal("");
  const pSpaces = useSignal("");
  const pObsessions = useSignal("");
  const pInterfaceValues = useSignal("");
  const pPetPeeves = useSignal("");
  const pColorTemp = useSignal("neutral");
  const pDensity = useSignal("rich");
  const pEdge = useSignal("soft");
  const pMotion = useSignal("smooth");
  const pTypography = useSignal("expressive");
  const pTexture = useSignal("textured");
  const pIcon = useSignal("line");
  const pLayout = useSignal("organic");

  const genSelected = useSignal("");
  const genType = useSignal("suite");
  const genDryRun = useSignal(false);
  const genRunning = useSignal(false);
  const genLogs = useSignal<string[]>([]);
  const genJobStatus = useSignal("");
  const genJobs = useSignal<Array<{ id: string; personaId: string; type: string; status: string }>>([]);

  const tokSelected = useSignal("");
  const tokFormat = useSignal("css");
  const tokContent = useSignal("");
  const tokLoading = useSignal(false);

  const showToast = $((msg: string, type = "success") => {
    toastMsg.value = msg;
    toastType.value = type;
    toastShow.value = true;
    setTimeout(() => toastShow.value = false, 3000);
  });

  const loadPersonas = $(() => {
    personasLoading.value = true;
    fetch(`${API_BASE}/personas`)
      .then((r) => r.json())
      .then((data) => { personas.value = data; personasLoading.value = false; })
      .catch(() => { personasLoading.value = false; });
  });

  useVisibleTask$(() => {
    loadPersonas();
    fetch(`${API_BASE}/jobs`).then((r) => r.json()).then((d) => { genJobs.value = d; }).catch(() => {});
  });

  const resetForm = $(() => {
    pId.value = "";
    pName.value = "";
    pSummary.value = "";
    pRegion.value = "";
    pSubcultures.value = "";
    pValues.value = "";
    pFilms.value = "";
    pAnime.value = "";
    pMusicGenres.value = "";
    pMusicArtists.value = "";
    pVisualArtists.value = "";
    pSpaces.value = "";
    pObsessions.value = "";
    pInterfaceValues.value = "";
    pPetPeeves.value = "";
    pColorTemp.value = "neutral";
    pDensity.value = "rich";
    pEdge.value = "soft";
    pMotion.value = "smooth";
    pTypography.value = "expressive";
    pTexture.value = "textured";
    pIcon.value = "line";
    pLayout.value = "organic";
    editingId.value = null;
  });

  const fillForm = $((p: any) => {
    pId.value = p.id;
    pName.value = p.name;
    pSummary.value = p.summary || "";
    pRegion.value = p.culture?.region || "";
    pSubcultures.value = (p.culture?.subcultures || []).join(", ");
    pValues.value = (p.culture?.values || []).join(", ");
    pFilms.value = (p.influences?.films || []).join(", ");
    pAnime.value = (p.influences?.anime || []).join(", ");
    pMusicGenres.value = (p.influences?.music?.genres || []).join(", ");
    pMusicArtists.value = (p.influences?.music?.artists || []).join(", ");
    pVisualArtists.value = (p.influences?.visualArtists || []).join(", ");
    pSpaces.value = (p.influences?.spaces || []).join(", ");
    pObsessions.value = (p.influences?.obsessions || []).join(", ");
    pInterfaceValues.value = (p.behaviors?.interfaceValues || []).join(", ");
    pPetPeeves.value = (p.behaviors?.petPeeves || []).join(", ");
    pColorTemp.value = p.aesthetic?.colorTemperature || "neutral";
    pDensity.value = p.aesthetic?.density || "rich";
    pEdge.value = p.aesthetic?.edgeStyle || "soft";
    pMotion.value = p.aesthetic?.motionStyle || "smooth";
    pTypography.value = p.aesthetic?.typographyStyle || "expressive";
    pTexture.value = p.aesthetic?.textureStyle || "textured";
    pIcon.value = p.aesthetic?.iconStyle || "line";
    pLayout.value = p.aesthetic?.layoutStyle || "organic";
  });

  const savePersona = $(() => {
    const split = (v: string) => v.split(",").map((s) => s.trim()).filter(Boolean);
    const persona = {
      id: pId.value.trim(),
      name: pName.value.trim() || pId.value.trim(),
      summary: pSummary.value.trim(),
      culture: { region: pRegion.value.trim() || undefined, subcultures: split(pSubcultures.value), values: split(pValues.value) },
      influences: {
        films: split(pFilms.value), shows: [], anime: split(pAnime.value),
        music: { genres: split(pMusicGenres.value), artists: split(pMusicArtists.value) },
        games: [], visualArtists: split(pVisualArtists.value), fashion: [], spaces: split(pSpaces.value),
        tools: [], obsessions: split(pObsessions.value),
      },
      behaviors: {
        discovery: [], interfaceValues: split(pInterfaceValues.value), platforms: [],
        expression: [], petPeeves: split(pPetPeeves.value),
      },
      aesthetic: {
        colorTemperature: pColorTemp.value, density: pDensity.value, edgeStyle: pEdge.value,
        motionStyle: pMotion.value, typographyStyle: pTypography.value, textureStyle: pTexture.value,
        iconStyle: pIcon.value, layoutStyle: pLayout.value,
        visualKeywords: [...split(pFilms.value), ...split(pAnime.value), ...split(pVisualArtists.value)].slice(0, 8),
        moodKeywords: [...split(pValues.value), ...split(pInterfaceValues.value)].slice(0, 6),
      },
    };
    const url = editingId.value ? `${API_BASE}/personas/${editingId.value}` : `${API_BASE}/personas`;
    const method = editingId.value ? "PUT" : "POST";
    fetch(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(persona) })
      .then((r) => { if (!r.ok) throw new Error(); showToast(editingId.value ? "Updated" : "Created"); resetForm(); activeTab.value = "personas"; loadPersonas(); })
      .catch(() => showToast("Save failed", "error"));
  });

  const loadTokens = $((id: string, fmt: string) => {
    if (!id) return;
    tokLoading.value = true;
    fetch(`${API_BASE}/tokens/${id}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ format: fmt }) })
      .then((r) => r.json())
      .then((data) => { tokContent.value = data.content || ""; tokLoading.value = false; })
      .catch(() => { tokLoading.value = false; });
  });

  const deletePersona = $((id: string) => {
    if (!confirm("Delete this persona?")) return;
    fetch(`${API_BASE}/personas/${id}`, { method: "DELETE" })
      .then(() => { showToast("Deleted"); loadPersonas(); })
      .catch(() => showToast("Delete failed", "error"));
  });

  const startGeneration = $(() => {
    if (!genSelected.value) { showToast("Select a persona", "warn"); return; }
    genRunning.value = true;
    genLogs.value = [];
    genJobStatus.value = "running";
    fetch(`${API_BASE}/generate/${genSelected.value}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ type: genType.value, dryRun: genDryRun.value }),
    })
      .then((r) => r.json())
      .then((data) => {
        genLogs.value = [`Job ${data.jobId} started`];
        const iv = setInterval(() => {
          fetch(`${API_BASE}/jobs/${data.jobId}`)
            .then((r) => r.json())
            .then((job) => {
              genJobStatus.value = job.status;
              genLogs.value = job.logs || [];
              if (job.status === "completed" || job.status === "error") {
                clearInterval(iv);
                genRunning.value = false;
                if (job.status === "completed") showToast("Generation complete!");
                else showToast(job.error || "Generation failed", "error");
                fetch(`${API_BASE}/jobs`).then((r) => r.json()).then((d) => { genJobs.value = d; }).catch(() => {});
              }
            })
            .catch(() => { clearInterval(iv); genRunning.value = false; });
        }, 1500);
      })
      .catch((err) => { genRunning.value = false; showToast(err.message, "error"); });
  });

  const previewPrompts = $(() => {
    if (!genSelected.value) { showToast("Select a persona", "warn"); return; }
    fetch(`${API_BASE}/prompts/${genSelected.value}`, { method: "POST" })
      .then((r) => r.json())
      .then((data) => {
        genLogs.value = ["--- Prompt Preview ---", `Image: ${data.image?.prompt?.slice(0, 200)}...`, `SVG: ${data.svg?.prompt?.slice(0, 200)}...`];
      })
      .catch(() => showToast("Preview failed", "error"));
  });

  const inputCls = css({ w: "full", bg: "bg", border: "1px solid token(colors.border)", color: "text", px: 3, py: 2, rounded: "md", fontSize: "sm" });
  const labelCls = css({ display: "block", fontSize: "xs", color: "text-muted", mb: 1 });
  const sectionTitle = css({ mt: 2, mb: 1, fontSize: "md", fontWeight: "semibold" });

  return (
    <>
      <Nav />
      <main class={css({ pt: "80px", minH: "100vh", bg: "bg" })}>
        <div class={flex({ maxW: "7xl", mx: "auto", px: 6, py: 8, direction: "column", gap: 6 })}>
          <div class={flex({ align: "center", justify: "space-between", wrap: "wrap", gap: 4 })}>
            <div>
              <h1 class={css({ fontFamily: "heading", fontSize: "2xl", fontWeight: "bold", bgGradient: "to-r", gradientFrom: "orange.500", gradientTo: "amber.500", bgClip: "text", color: "transparent" })}>
                Baste Dashboard
              </h1>
              <p class={css({ color: "text-muted", fontSize: "sm", mt: 1 })}>
                Manage personas, generate assets, export design tokens
              </p>
            </div>
            <div class={hstack({ gap: 2, bg: "surface", p: 1, rounded: "lg", border: "1px solid token(colors.border)" })}>
              {(["personas", "create", "generate", "tokens"] as const).map((tab) => (
                <button
                  key={tab}
                  onClick$={() => { activeTab.value = tab; if (tab === "create") { resetForm(); editingId.value = null; } }}
                  class={css({
                    px: 4, py: 2, rounded: "md", fontSize: "sm", fontWeight: "medium", cursor: "pointer", border: "none",
                    transition: "all 0.2s",
                    bg: activeTab.value === tab ? "accent" : "transparent",
                    color: activeTab.value === tab ? "white" : "text-muted",
                    _hover: { bg: activeTab.value === tab ? "accent" : "surface-hover", color: activeTab.value === tab ? "white" : "text" },
                  })}
                >
                  {tab === "personas" ? "Personas" : tab === "create" ? (editingId.value ? "Edit" : "Create") : tab === "generate" ? "Generate" : "Tokens"}
                </button>
              ))}
            </div>
          </div>

          {activeTab.value === "personas" && (
            <div>
              <div class={flex({ align: "center", justify: "space-between", mb: 4 })}>
                <h2 class={css({ fontFamily: "heading", fontSize: "xl", fontWeight: "semibold" })}>Your Personas</h2>
                <button onClick$={loadPersonas} class={css({ px: 3, py: 1.5, rounded: "md", bg: "surface-hover", color: "text", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border" } })}>Refresh</button>
              </div>
              {personasLoading.value && personas.value.length === 0 && (
                <div class={css({ color: "text-muted", textAlign: "center", py: 12 })}>Loading personas...</div>
              )}
              {!personasLoading.value && personas.value.length === 0 && (
                <div class={css({ color: "text-muted", textAlign: "center", py: 12 })}>No personas yet. Create your first!</div>
              )}
              <div class={grid({ columns: { base: 1, md: 2, lg: 3 }, gap: 4 })}>
                {personas.value.map((p) => (
                  <div key={p.id} class={css({ bg: "surface", border: "1px solid token(colors.border)", rounded: "lg", p: 5, transition: "all 0.2s", _hover: { borderColor: "accent", transform: "translateY(-2px)" } })}>
                    <div class={flex({ align: "center", justify: "space-between", mb: 2 })}>
                      <h3 class={css({ fontWeight: "semibold", fontSize: "lg" })}>{p.name}</h3>
                      <span class={css({ fontSize: "xs", px: 2, py: 0.5, rounded: "sm", bg: p._source === "base" ? "rgba(46,204,113,0.15)" : "rgba(230,126,34,0.15)", color: p._source === "base" ? "success" : "#e67e22" })}>{p._source || "base"}</span>
                    </div>
                    <p class={css({ color: "text-muted", fontSize: "sm", mb: 3 })}>{p.summary || "No summary"}</p>
                    <div class={hstack({ gap: 2, mb: 3 })}>
                      {p.aesthetic?.colorTemperature && <span class={css({ fontSize: "xs", px: 2, py: 0.5, rounded: "sm", bg: "rgba(123,104,238,0.15)", color: "accent-hover" })}>{p.aesthetic.colorTemperature}</span>}
                      {p.aesthetic?.density && <span class={css({ fontSize: "xs", px: 2, py: 0.5, rounded: "sm", bg: "rgba(123,104,238,0.15)", color: "accent-hover" })}>{p.aesthetic.density}</span>}
                    </div>
                    <div class={hstack({ gap: 2 })}>
                      <button onClick$={() => { genSelected.value = p.id; activeTab.value = "generate"; }} class={css({ flex: 1, px: 3, py: 1.5, rounded: "md", bg: "accent", color: "white", fontSize: "sm", fontWeight: "medium", border: "none", cursor: "pointer", _hover: { bg: "accent-hover" } })}>Generate</button>
                      <button onClick$={() => { tokSelected.value = p.id; loadTokens(p.id, tokFormat.value); activeTab.value = "tokens"; }} class={css({ px: 3, py: 1.5, rounded: "md", bg: "surface-hover", color: "text", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border" } })}>Tokens</button>
                      {p._source !== "base" && (
                        <>
                          <button onClick$={() => { fetch(`${API_BASE}/personas/${p.id}`).then((r) => r.json()).then((data) => { fillForm(data); editingId.value = p.id; activeTab.value = "create"; }); }} class={css({ px: 3, py: 1.5, rounded: "md", bg: "surface-hover", color: "text-muted", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border", color: "text" } })}>Edit</button>
                          <button onClick$={() => deletePersona(p.id)} class={css({ px: 3, py: 1.5, rounded: "md", bg: "surface-hover", color: "text-muted", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border", color: "text" } })}>Del</button>
                        </>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab.value === "create" && (
            <div class={css({ maxW: "800px" })}>
              <div class={flex({ align: "center", justify: "space-between", mb: 4, wrap: "wrap", gap: 2 })}>
                <h2 class={css({ fontFamily: "heading", fontSize: "xl", fontWeight: "semibold" })}>{editingId.value ? "Edit Persona" : "Create Persona"}</h2>
                <div class={flex({ gap: 2 })}>
                  <button onClick$={() => { resetForm(); activeTab.value = "personas"; }} class={css({ px: 4, py: 2, rounded: "md", bg: "surface-hover", color: "text", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border" } })}>Cancel</button>
                  <button onClick$={savePersona} class={css({ px: 4, py: 2, rounded: "md", bg: "accent", color: "white", fontSize: "sm", fontWeight: "medium", border: "none", cursor: "pointer", _hover: { bg: "accent-hover" } })}>Save</button>
                </div>
              </div>
              <div class={grid({ gap: 4 })}>
                <div><label class={labelCls}>ID (kebab-case)</label><input value={pId.value} onInput$={(e) => { pId.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="my-persona" /></div>
                <div><label class={labelCls}>Name</label><input value={pName.value} onInput$={(e) => { pName.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="My Persona Name" /></div>
                <div><label class={labelCls}>Summary</label><textarea value={pSummary.value} onInput$={(e) => { pSummary.value = (e.target as HTMLTextAreaElement).value; }} class={inputCls} placeholder="Brief description..." style={{ minHeight: "80px" }} /></div>

                <h3 class={sectionTitle}>Culture</h3>
                <div class={grid({ columns: { base: 1, md: 2 }, gap: 4 })}>
                  <div><label class={labelCls}>Region</label><input value={pRegion.value} onInput$={(e) => { pRegion.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="e.g. Pacific Northwest" /></div>
                  <div><label class={labelCls}>Subcultures</label><input value={pSubcultures.value} onInput$={(e) => { pSubcultures.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="solarpunk, biohacking" /></div>
                </div>
                <div><label class={labelCls}>Values</label><input value={pValues.value} onInput$={(e) => { pValues.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="interconnectedness, growth" /></div>

                <h3 class={sectionTitle}>Influences</h3>
                <div class={grid({ columns: { base: 1, md: 2 }, gap: 4 })}>
                  <div><label class={labelCls}>Films</label><input value={pFilms.value} onInput$={(e) => { pFilms.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="Annihilation, Nausicaä" /></div>
                  <div><label class={labelCls}>Anime</label><input value={pAnime.value} onInput$={(e) => { pAnime.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="Mushishi" /></div>
                  <div><label class={labelCls}>Music Genres</label><input value={pMusicGenres.value} onInput$={(e) => { pMusicGenres.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="ambient" /></div>
                  <div><label class={labelCls}>Music Artists</label><input value={pMusicArtists.value} onInput$={(e) => { pMusicArtists.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="Biosphere" /></div>
                </div>
                <div><label class={labelCls}>Visual Artists</label><input value={pVisualArtists.value} onInput$={(e) => { pVisualArtists.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="Ernst Haeckel" /></div>
                <div><label class={labelCls}>Spaces</label><input value={pSpaces.value} onInput$={(e) => { pSpaces.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="greenhouses" /></div>
                <div><label class={labelCls}>Obsessions</label><input value={pObsessions.value} onInput$={(e) => { pObsessions.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="mycelial networks" /></div>

                <h3 class={sectionTitle}>Behaviors</h3>
                <div class={grid({ columns: { base: 1, md: 2 }, gap: 4 })}>
                  <div><label class={labelCls}>Interface Values</label><input value={pInterfaceValues.value} onInput$={(e) => { pInterfaceValues.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="discoverability" /></div>
                  <div><label class={labelCls}>Pet Peeves</label><input value={pPetPeeves.value} onInput$={(e) => { pPetPeeves.value = (e.target as HTMLInputElement).value; }} class={inputCls} placeholder="dark patterns" /></div>
                </div>

                <h3 class={sectionTitle}>Aesthetic</h3>
                <div class={grid({ columns: { base: 1, md: 2 }, gap: 4 })}>
                  {AESTHETIC_FIELDS.map((f) => {
                    const valMap: Record<string, any> = {
                      colorTemperature: pColorTemp, density: pDensity, edgeStyle: pEdge, motionStyle: pMotion,
                      typographyStyle: pTypography, textureStyle: pTexture, iconStyle: pIcon, layoutStyle: pLayout,
                    };
                    const s = valMap[f.key];
                    return (
                      <div key={f.key}>
                        <label class={labelCls}>{f.label}</label>
                        <select value={s.value} onChange$={(e) => { s.value = (e.target as HTMLSelectElement).value; }} class={inputCls}>
                          {f.options.map((o) => <option key={o} value={o}>{o.charAt(0).toUpperCase() + o.slice(1)}</option>)}
                        </select>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}

          {activeTab.value === "generate" && (
            <div>
              <h2 class={css({ fontFamily: "heading", fontSize: "xl", fontWeight: "semibold", mb: 4 })}>Generate Assets</h2>
              <div class={grid({ columns: { base: 1, md: 2 }, gap: 4, mb: 4 })}>
                <div>
                  <label class={labelCls}>Persona</label>
                  <select value={genSelected.value} onChange$={(e) => { genSelected.value = (e.target as HTMLSelectElement).value; }} class={inputCls}>
                    <option value="">-- Choose --</option>
                    {personas.value.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </select>
                </div>
                <div>
                  <label class={labelCls}>Type</label>
                  <select value={genType.value} onChange$={(e) => { genType.value = (e.target as HTMLSelectElement).value; }} class={inputCls}>
                    <option value="suite">Asset Suite</option>
                    <option value="ui-kit">Full UI Kit</option>
                  </select>
                </div>
              </div>
              <div class={flex({ align: "center", gap: 3, mb: 4 })}>
                <label class={css({ display: "flex", alignItems: "center", gap: 2, fontSize: "sm", color: "text-muted", cursor: "pointer" })}>
                  <input type="checkbox" checked={genDryRun.value} onChange$={(e) => { genDryRun.value = (e.target as HTMLInputElement).checked; }} />
                  Dry Run
                </label>
                {genJobStatus.value && (
                  <span class={css({ fontSize: "sm", px: 2, py: 0.5, rounded: "sm", bg: genJobStatus.value === "completed" ? "rgba(46,204,113,0.15)" : genJobStatus.value === "error" ? "rgba(231,76,60,0.15)" : "rgba(243,156,18,0.15)", color: genJobStatus.value === "completed" ? "success" : genJobStatus.value === "error" ? "danger" : "orange.500" })}>{genJobStatus.value}</span>
                )}
              </div>
              <div class={hstack({ gap: 2, mb: 4 })}>
                <button onClick$={startGeneration} disabled={genRunning.value} class={css({ px: 4, py: 2, rounded: "md", bg: "accent", color: "white", fontSize: "sm", fontWeight: "medium", border: "none", cursor: genRunning.value ? "not-allowed" : "pointer", opacity: genRunning.value ? 0.5 : 1, _hover: genRunning.value ? {} : { bg: "accent-hover" } })}>{genRunning.value ? "Generating..." : "Start Generation"}</button>
                <button onClick$={previewPrompts} class={css({ px: 4, py: 2, rounded: "md", bg: "surface-hover", color: "text", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border" } })}>Preview Prompts</button>
                <button onClick$={() => { fetch(`${API_BASE}/jobs`).then((r) => r.json()).then((d) => { genJobs.value = d; }); }} class={css({ px: 4, py: 2, rounded: "md", bg: "surface-hover", color: "text", fontSize: "sm", border: "1px solid token(colors.border)", cursor: "pointer", _hover: { bg: "border" } })}>Refresh Jobs</button>
              </div>
              <div class={css({ bg: "surface", border: "1px solid token(colors.border)", rounded: "lg", overflow: "hidden", mb: 4 })}>
                <div class={css({ bg: "surface-hover", px: 4, py: 2, fontSize: "xs", color: "text-muted", borderBottom: "1px solid token(colors.border)", display: "flex", justifyContent: "space-between", alignItems: "center" })}>
                  <span>Generation Logs</span>
                  <button onClick$={() => genLogs.value = []} class={css({ px: 2, py: 0.5, rounded: "sm", bg: "transparent", color: "text-muted", fontSize: "xs", border: "none", cursor: "pointer", _hover: { color: "text" } })}>Clear</button>
                </div>
                <div class={css({ p: 4, fontFamily: "mono", fontSize: "xs", lineHeight: 1.6, maxH: "300px", overflowY: "auto", color: "text-muted" })}>
                  {genLogs.value.length === 0 && <div><span class={css({ color: "#5a5a7a" })}>{new Date().toLocaleTimeString()}</span> Ready. Select a persona and start generation.</div>}
                  {genLogs.value.map((log, i) => <div key={i}><span class={css({ color: "#5a5a7a" })}>{new Date().toLocaleTimeString()}</span> {log}</div>)}
                </div>
              </div>
              <h3 class={css({ fontSize: "md", fontWeight: "semibold", mb: 2 })}>Recent Jobs</h3>
              {genJobs.value.length === 0 && <div class={css({ color: "text-muted", fontSize: "sm" })}>No jobs yet.</div>}
              <div class={flex({ direction: "column", gap: 1 })}>
                {genJobs.value.map((j) => <div key={j.id} class={css({ fontSize: "xs", px: 2, py: 1, rounded: "sm", bg: "surface-hover", color: "text-muted" })}>{j.id} — {j.type} for {j.personaId} ({j.status})</div>)}
              </div>
            </div>
          )}

          {activeTab.value === "tokens" && (
            <div>
              <h2 class={css({ fontFamily: "heading", fontSize: "xl", fontWeight: "semibold", mb: 4 })}>Export Design Tokens</h2>
              <div class={flex({ gap: 3, mb: 4, wrap: "wrap" })}>
                <div>
                  <label class={labelCls}>Persona</label>
                  <select value={tokSelected.value} onChange$={(e) => { tokSelected.value = (e.target as HTMLSelectElement).value; if (tokSelected.value) loadTokens(tokSelected.value, tokFormat.value); else tokContent.value = ""; }} class={css({ w: "64", bg: "bg", border: "1px solid token(colors.border)", color: "text", px: 3, py: 2, rounded: "md", fontSize: "sm" })}>
                    <option value="">-- Choose --</option>
                    {personas.value.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </select>
                </div>
                <div>
                  <label class={labelCls}>Format</label>
                  <select value={tokFormat.value} onChange$={(e) => { tokFormat.value = (e.target as HTMLSelectElement).value; if (tokSelected.value) loadTokens(tokSelected.value, tokFormat.value); }} class={css({ w: "48", bg: "bg", border: "1px solid token(colors.border)", color: "text", px: 3, py: 2, rounded: "md", fontSize: "sm" })}>
                    <option value="css">CSS Custom Properties</option>
                    <option value="tailwind">Tailwind Config (JS)</option>
                    <option value="json">JSON Tokens</option>
                    <option value="panda">PandaCSS Theme (TS)</option>
                  </select>
                </div>
              </div>
              {tokLoading.value && <div class={css({ color: "text-muted", textAlign: "center", py: 8 })}>Loading tokens...</div>}
              {!tokLoading.value && tokContent.value && (
                <>
                  <div class={hstack({ gap: 2, mb: 3 })}>
                    <button onClick$={() => { if (!tokContent.value || !tokSelected.value) return; const extMap: Record<string, string> = { css: "css", tailwind: "js", json: "json", panda: "ts" }; const ext = extMap[tokFormat.value] || "txt"; const blob = new Blob([tokContent.value], { type: "text/plain" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `${tokSelected.value}-tokens.${ext}`; a.click(); showToast(`Downloaded ${tokFormat.value === "panda" ? "PandaCSS" : tokFormat.value.toUpperCase()}`); }} class={css({ px: 4, py: 2, rounded: "md", bg: "accent", color: "white", fontSize: "sm", fontWeight: "medium", border: "none", cursor: "pointer", _hover: { bg: "accent-hover" } })}>Download {tokFormat.value === "panda" ? "PandaCSS" : tokFormat.value.toUpperCase()}</button>
                  </div>
                  <pre class={css({ bg: "bg", border: "1px solid token(colors.border)", rounded: "lg", p: 4, fontFamily: "mono", fontSize: "xs", color: "text-muted", maxH: "500px", overflow: "auto", whiteSpace: "pre-wrap", wordBreak: "break-word" })}>{tokContent.value}</pre>
                </>
              )}
              {!tokLoading.value && !tokContent.value && tokSelected.value && (
                <div class={css({ color: "text-muted", textAlign: "center", py: 8 })}>Select a format to preview tokens.</div>
              )}
            </div>
          )}
        </div>
      </main>
      <Footer />
      {toastShow.value && (
        <div class={css({ position: "fixed", bottom: 6, right: 6, bg: "surface", border: "1px solid", borderColor: toastType.value === "error" ? "danger" : toastType.value === "warn" ? "orange.500" : "success", px: 4, py: 3, rounded: "lg", fontSize: "sm", zIndex: 200 })}>{toastMsg.value}</div>
      )}
    </>
  );
});

export const head: DocumentHead = {
  title: "Baste Dashboard — Persona Manager",
};

content.content:
1	/**
2	 * Design System Exporter
3	 * 
4	 * Converts a persona's aesthetic profile into usable design tokens:
5	 * - CSS custom properties (variables)
6	 * - Tailwind config extensions
7	 * - Theme objects for styled-components, emotion, etc.
8	 * - Color palettes generated from persona keywords
9	 */
10	
11	import type { Persona, AestheticProfile } from "../persona/types.js";
12	
13	export interface DesignTokens {
14	  colors: ColorPalette;
15	  typography: TypographyTokens;
16	  spacing: SpacingTokens;
17	  borders: BorderTokens;
18	  shadows: ShadowTokens;
19	  motion: MotionTokens;
20	}
21	
22	export interface ColorPalette {
23	  // Generated from persona aesthetic
24	  primary: string;
25	  secondary: string;
26	  accent: string;
27	  background: string;
28	  surface: string;
29	  text: string;
30	  textMuted: string;
31	  border: string;
32	  // Temperature-based extras
33	  warm: string;
34	  cool: string;
35	  // Density-based
36	  density: "minimal" | "dense" | "rich" | "maximalist";
37	}
38	
39	export interface TypographyTokens {
40	  fontFamily: {
41	    heading: string;
42	    body: string;
43	    mono: string;
44	  };
45	  fontSize: {
46	    xs: string;
47	    sm: string;
48	    base: string;
49	    lg: string;
50	    xl: string;
51	    "2xl": string;
52	    "3xl": string;
53	    "4xl": string;
54	  };
55	  fontWeight: {
56	    normal: number;
57	    medium: number;
58	    semibold: number;
59	    bold: number;
60	  };
61	  lineHeight: {
62	    tight: number;
63	    normal: number;
64	    relaxed: number;
65	  };
66	}
67	
68	export interface SpacingTokens {
69	  scale: Record<string, string>;
70	  density: "minimal" | "dense" | "rich" | "maximalist";
71	}
72	
73	export interface BorderTokens {
74	  radius: {
75	    none: string;
76	    sm: string;
77	    base: string;
78	    lg: string;
79	    xl: string;
80	    full: string;
81	  };
82	  width: {
83	    thin: string;
84	    base: string;
85	    thick: string;
86	  };
87	  style: string;
88	}
89	
90	export interface ShadowTokens {
91	  sm: string;
92	  base: string;
93	  lg: string;
94	  xl: string;
95	  glow: string;
96	}
97	
98	export interface MotionTokens {
99	  duration: {
100	    fast: string;
101	    base: string;
102	    slow: string;
103	    slower: string;
104	  };
105	  easing: {
106	    default: string;
107	    smooth: string;
108	    snappy: string;
109	    bounce: string;
110	  };
111	}
112	
113	/**
114	 * Generate design tokens from persona
115	 */
116	export function generateDesignTokens(persona: Persona): DesignTokens {
117	  const aesthetic = persona.aesthetic;
118	
119	  return {
120	    colors: generateColorPalette(aesthetic),
121	    typography: generateTypography(aesthetic),
122	    spacing: generateSpacing(aesthetic),
123	    borders: generateBorders(aesthetic),
124	    shadows: generateShadows(aesthetic),
125	    motion: generateMotion(aesthetic),
126	  };
127	}
128	
129	function generateColorPalette(aesthetic: AestheticProfile): ColorPalette {
130	  const colorMap: Record<string, ColorPalette> = {
131	    warm: {
132	      primary: "#8B6914",
133	      secondary: "#6B8E6B",
134	      accent: "#D4A843",
135	      background: "#F5F0E8",
136	      surface: "#FFFFFF",
137	      text: "#2D2926",
138	      textMuted: "#7A756E",
139	      border: "#D9D4CC",
140	      warm: "#D4A843",
141	      cool: "#7BA3A8",
142	      density: aesthetic.density,
143	    },
144	    cool: {
145	      primary: "#4A6FA5",
146	      secondary: "#6B5B95",
147	      accent: "#88B0C4",
148	      background: "#1A1F2E",
149	      surface: "#242B3D",
150	      text: "#E8E8F0",
151	      textMuted: "#8A8FA8",
152	      border: "#3A4055",
153	      warm: "#C4956A",
154	      cool: "#88B0C4",
155	      density: aesthetic.density,
156	    },
157	    "high-contrast": {
158	      primary: "#FF6B35",
159	      secondary: "#004E89",
160	      accent: "#1A659E",
161	      background: "#0A0A0A",
162	      surface: "#141414",
163	      text: "#FFFFFF",
164	      textMuted: "#999999",
165	      border: "#333333",
166	      warm: "#FF6B35",
167	      cool: "#00A8E8",
168	      density: aesthetic.density,
169	    },
170	    muted: {
171	      primary: "#9B8E7E",
172	      secondary: "#A8B5A6",
173	      accent: "#C4B8A8",
174	      background: "#FAF8F5",
175	      surface: "#FFFFFF",
176	      text: "#4A4540",
177	      textMuted: "#9A948C",
178	      border: "#E8E4DE",
179	      warm: "#C4B8A8",
180	      cool: "#A8B5C4",
181	      density: aesthetic.density,
182	    },
183	    neutral: {
184	      primary: "#5A5A5A",
185	      secondary: "#7A7A7A",
186	      accent: "#3A7CA5",
187	      background: "#F7F7F7",
188	      surface: "#FFFFFF",
189	      text: "#1A1A1A",
190	      textMuted: "#6A6A6A",
191	      border: "#E0E0E0",
192	      warm: "#C4A882",
193	      cool: "#82A8C4",
194	      density: aesthetic.density,
195	    },
196	  };
197	
198	  return colorMap[aesthetic.colorTemperature] || colorMap.neutral;
199	}
200	
201	function generateTypography(aesthetic: AestheticProfile): TypographyTokens {
202	  const fontMap: Record<string, { heading: string; body: string; mono: string }> = {
203	    clean: {
204	      heading: "'Inter', system-ui, sans-serif",
205	      body: "'Inter', system-ui, sans-serif",
206	      mono: "'JetBrains Mono', monospace",
207	    },
208	    expressive: {
209	      heading: "'Space Grotesk', 'Helvetica Neue', sans-serif",
210	      body: "'Source Sans 3', system-ui, sans-serif",
211	      mono: "'Fira Code', monospace",
212	    },
213	    retro: {
214	      heading: "'Space Grotesk', 'Courier New', serif",
215	      body: "'Source Sans 3', Georgia, serif",
216	      mono: "'Courier Prime', monospace",
217	    },
218	    futuristic: {
219	      heading: "'Rajdhani', 'Helvetica Neue', sans-serif",
220	      body: "'Inter', system-ui, sans-serif",
221	      mono: "'JetBrains Mono', monospace",
222	    },
223	    handcrafted: {
224	      heading: "'Space Grotesk', 'Palatino', serif",
225	      body: "'Source Sans 3', 'Palatino', serif",
226	      mono: "'Fira Code', monospace",
227	    },
228	  };
229	
230	  const fonts = fontMap[aesthetic.typographyStyle] || fontMap.clean;
231	
232	  return {
233	    fontFamily: fonts,
234	    fontSize: {
235	      xs: "0.75rem",
236	      sm: "0.875rem",
237	      base: "1rem",
238	      lg: "1.125rem",
239	      xl: "1.25rem",
240	      "2xl": "1.5rem",
241	      "3xl": "2rem",
242	      "4xl": "2.5rem",
243	    },
244	    fontWeight: {
245	      normal: 400,
246	      medium: 500,
247	      semibold: 600,
248	      bold: 700,
