584	  theme: {
585	    extend: {
586	      tokens: {
587	        colors: {
588	          bg: { value: "${t.colors.background}" },
589	          surface: { value: "${t.colors.surface}" },
590	          "surface-hover": { value: "${shadeColor(t.colors.surface, 10)}" },
591	          text: { value: "${t.colors.text}" },
592	          "text-muted": { value: "${t.colors.textMuted}" },
593	          border: { value: "${t.colors.border}" },
594	          primary: { value: "${t.colors.primary}" },
595	          secondary: { value: "${t.colors.secondary}" },
596	          accent: { value: "${t.colors.accent}" },
597	          warm: { value: "${t.colors.warm}" },
598	          cool: { value: "${t.colors.cool}" },
599	        },
600	        fonts: {
601	          heading: { value: "${t.typography.fontFamily.heading}" },
602	          body: { value: "${t.typography.fontFamily.body}" },
603	          mono: { value: "${t.typography.fontFamily.mono}" },
604	        },
