607	          base: { value: "${t.borders.radius.base}" },
608	          lg: { value: "${t.borders.radius.lg}" },
609	          xl: { value: "${t.borders.radius.xl}" },
610	        },
611	        spacing: {
612	          ${Object.entries(t.spacing.scale).map(([k, v]) => `${k}: { value: "${v}" },`).join("\n          ")}
613	        },
614	      },
615	      keyframes: {
