626	
627	function shadeColor(color: string, percent: number): string {
628	  // Simple hex shade — darken/lighten
629	  const num = parseInt(color.replace("#", ""), 16);
630	  const amt = Math.round(2.55 * percent);
631	  const R = (num >> 16) + amt;
632	  const G = ((num >> 8) & 0x00ff) + amt;
633	  const B = (num & 0x0000ff) + amt;
634	  return (
635	    "#" +
636	    (
637	      0x1000000 +
638	      (R < 255 ? (R < 1 ? 0 : R) : 255) * 0x10000 +
639	      (G < 255 ? (G < 1 ? 0 : G) : 255) * 0x100 +
640	      (B < 255 ? (B < 1 ? 0 : B) : 255)
641	    )
642	      .toString(16)
643	      .slice(1)
644	  );
645	}
