45	interface RouteHandler {
46	  (req: IncomingMessage, res: ServerResponse, params: Record<string, string>): Promise<void>;
47	}
48	
49	function json(res: ServerResponse, data: unknown, status = 200): void {
50	  res.writeHead(status, { "Content-Type": "application/json" });
51	  res.end(JSON.stringify(data));
52	}
53	
54	function parseBody(req: IncomingMessage): Promise<unknown> {
55	  return new Promise((resolve, reject) => {
56	    let body = "";
57	    req.on("data", (chunk) => { body += chunk.toString(); });
58	    req.on("end", () => {
59	      try {
60	        resolve(JSON.parse(body));
61	      } catch {
62	        resolve({});
63	      }
64	    });
65	    req.on("error", reject);
66	  });
67	}
68	
69	async function corsMiddleware(
70	  req: IncomingMessage,
71	  res: ServerResponse,
72	  next: () => Promise<void>
73	): Promise<void> {
74	  res.setHeader("Access-Control-Allow-Origin", "*");
75	  res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
76	  res.setHeader("Access-Control-Allow-Headers", "Content-Type");
77	
78	  if (req.method === "OPTIONS") {
79	    res.writeHead(204);
80	    res.end();
81	    return;
82	  }
83	  await next();
84	}
