91	  const ids = listPersonas();
92	  const personas = ids.map((id) => {
93	    const p = getPersona(id)!;
94	    return { ...p, _source: isBasePersona(id) ? "base" : "custom" };
95	  });
96	  json(res, personas);
97	};
