102	 */
103	const getPersonaHandler: RouteHandler = async (_req, res, params) => {
104	  const persona = getPersona(params.id);
105	  if (!persona) {
106	    json(res, { error: "Persona not found" }, 404);
107	    return;
108	  }
109	  json(res, { ...persona, _source: isBasePersona(params.id) ? "base" : "custom" });
110	};
