112	/**
113	 * Route: POST /api/personas
114	 * Create a new custom persona.
115	 */
116	const createPersonaHandler: RouteHandler = async (req, res) => {
117	  const body = await parseBody(req) as Persona;
118	  if (!body.id || !body.name) {
119	    json(res, { error: "id and name are required" }, 400);
120	    return;
