              <div key={c.token} class={css({ rounded: "md", overflow: "hidden", border: "2px solid token(colors.ink-black)" })}>
                <div style={{ background: c.hex, height: "60px" }} />
                <div class={css({ p: 2, fontSize: "10px", bg: "ink-black", fontFamily: "mono" })}>
